import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Résolution des problèmes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/depannage.md","filePath":"guide/depannage.md"}'),n={name:"guide/depannage.md"};function s(d,e,i,l,u,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="resolution-des-problemes" tabindex="-1">Résolution des problèmes <a class="header-anchor" href="#resolution-des-problemes" aria-label="Permalink to &quot;Résolution des problèmes&quot;">​</a></h1><p>Dans la grande majorité des cas, un dysfonctionnement provient d&#39;un mod : désactivez le dernier mod ajouté, puis relancez le jeu.</p><h2 id="en-cas-de-plantage-de-minecraft" tabindex="-1">En cas de plantage de Minecraft <a class="header-anchor" href="#en-cas-de-plantage-de-minecraft" aria-label="Permalink to &quot;En cas de plantage de Minecraft&quot;">​</a></h2><p>Kodus ouvre une fenêtre <strong>« Minecraft a planté »</strong> qui indique la cause du problème et propose une correction en un clic :</p><ul><li><strong>Mod manquant</strong> : bouton pour l&#39;installer.</li><li><strong>Mod incompatible avec votre version</strong>, ou <strong>mods incompatibles entre eux</strong> : bouton pour désactiver le mod concerné.</li><li><strong>Mémoire insuffisante</strong> : bouton pour modifier la RAM allouée.</li><li><strong>Loader obsolète</strong> : bouton pour le mettre à jour.</li></ul><p>Après correction, cliquez sur <strong>Relancer</strong>. Si la cause n&#39;est pas identifiée, Kodus affiche des recommandations générales ainsi que le bouton <strong>Copier le diagnostic</strong>, à transmettre à l&#39;équipe Kodus.</p><h2 id="problemes-courants" tabindex="-1">Problèmes courants <a class="header-anchor" href="#problemes-courants" aria-label="Permalink to &quot;Problèmes courants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problème</th><th>Solution</th></tr></thead><tbody><tr><td>Le jeu se ferme ou plante au lancement</td><td>Suivez les indications de la fenêtre « Minecraft a planté ». À défaut, désactivez les derniers mods ajoutés (interrupteur dans la colonne Installés) et relancez. Si le problème disparaît, réactivez-les un par un pour identifier le mod en cause.</td></tr><tr><td>Message « Mod incompatible » ou « requires … »</td><td>Un mod ne correspond pas à votre version ou à votre loader, ou une dépendance manque. Cliquez sur <strong>Tout mettre à jour</strong> ; à défaut, retirez le mod.</td></tr><tr><td>Le jeu manque de fluidité</td><td>Installez <strong>Sodium</strong>. Avec des shaders, choisissez-en un plus léger ou désactivez-les (Échap → Options → Shader packs).</td></tr><tr><td>Message « Out of memory », le jeu se fige puis plante</td><td>Augmentez légèrement la RAM dans ⚙ Gérer (par exemple de 4 à 6 Go), sans dépasser la moitié de la mémoire de l&#39;ordinateur.</td></tr><tr><td>Impossible de rejoindre un autre joueur</td><td>Les deux joueurs doivent avoir la même version, le même loader et les mêmes mods : le plus simple est de partager un <code>.kpack</code>.</td></tr><tr><td>Le skin ne s&#39;affiche pas</td><td>Vérifiez que l&#39;instance utilise un loader (et non Vanilla) et que l&#39;option « Skins Kodus » est cochée dans ⚙ Gérer. Un nouveau skin peut mettre jusqu&#39;à une minute à apparaître.</td></tr><tr><td>Message « Ce pseudo est déjà réservé »</td><td>Ce pseudo est déjà associé à un skin. Choisissez-en un autre, ou contactez l&#39;équipe Kodus s&#39;il s&#39;agit du vôtre (changement d&#39;ordinateur).</td></tr><tr><td>Windows bloque l&#39;installation</td><td>Consultez <a href="./installer">Installer Kodus</a> : option « Exécuter quand même » ou version portable.</td></tr><tr><td>Kodus ne s&#39;ouvre pas sur Mac</td><td>macOS 13 ou une version ultérieure est requis : consultez <a href="./installer#macos">Installer Kodus</a>.</td></tr><tr><td>Kodus ne se lance pas sous Linux</td><td>Vérifiez que le fichier est exécutable, puis consultez <a href="./installer#linux">Installer Kodus</a> (FUSE 2, option <code>--no-sandbox</code>).</td></tr><tr><td>Le premier lancement est très long</td><td>C&#39;est normal : Java et le jeu sont téléchargés une seule fois. Suivez la barre de progression.</td></tr></tbody></table><h2 id="obtenir-de-l-aide" tabindex="-1">Obtenir de l&#39;aide <a class="header-anchor" href="#obtenir-de-l-aide" aria-label="Permalink to &quot;Obtenir de l&#39;aide&quot;">​</a></h2><p>Si le problème persiste, transmettez vos logs à l&#39;équipe Kodus : page de l&#39;instance → onglet <strong>Logs</strong> → <strong>Copier</strong>, puis collez-les dans votre message. Précisez également l&#39;action en cours au moment du problème, ainsi que le dernier mod ajouté.</p>',10)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
